java.solution:
import java.util.Scanner;

public class Main {
    static int[] rotateLeft(int a, int b, int c) {
        int oldA = a;
        a = b;
        b = c;
        c = oldA;
        return new int[] {a, b, c};
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int a = in.nextInt();
        int b = in.nextInt();
        int c = in.nextInt();
        int[] rotated = rotateLeft(a, b, c);
        System.out.println(rotated[0] + " " + rotated[1] + " " + rotated[2]);
    }
}

